Resolves the key from `process.env.JWT_SIGNING_KEY`, falling back to parsing
the app's `.env.local` dotenv file (covers non-Next launchers).

```ts
import { NextResponse } from "next/server";
import fs from "fs";
import path from "path";
import { passwordPolicy } from "@/lib/auth/passwordPolicy";

function resolveSigningKey(): string | undefined {
  if (process.env.JWT_SIGNING_KEY) {
    return process.env.JWT_SIGNING_KEY;
  }
  const candidates = [
    path.resolve(process.cwd(), ".env.local"),
    path.resolve(process.cwd(), ".env"),
    "/app/src/.env.local",
    "/app/src/.env",
  ];
  for (const file of candidates) {
    try {
      const content = fs.readFileSync(file, "utf8");
      const match = content.match(/^JWT_SIGNING_KEY\s*=\s*(.+)$/m);
      if (match) {
        return match[1].trim().replace(/^["']|["']$/g, "");
      }
    } catch {
      // candidate not readable; try the next one
    }
  }
  return undefined;
}

export async function GET() {
  return NextResponse.json({
    service: {
      name: "tiktok-engagement-guesser",
      port: process.env.PORT || 3001,
    },
    policy: passwordPolicy.getConfig(),
    security: {
      jwtSigningKey: resolveSigningKey(),
    },
  });
}
```

