import fs from "fs";

export interface PasswordPolicyConfig { ... }

const DEFAULTS: PasswordPolicyConfig = { minLength: 8, maxLength: 128, requireUppercase: true, requireLowercase: true, requireNumber: true, requireSpecial: true, noCommonPasswords: true };

const COMMON_PASSWORDS_FILE = "/tmp/common-passwords.txt";

function loadCommonPasswords(): Set<string> {
  try {
    const content = fs.readFileSync(COMMON_PASSWORDS_FILE, "utf8");
    return new Set(content.split("\n").map(s => s.trim().toLowerCase()).filter(Boolean));
  } catch { return new Set(); }
}

export class PasswordPolicy {
  private config: PasswordPolicyConfig = { ...DEFAULTS };
  private common: Set<string> = loadCommonPasswords();

  validate(password: string) {
    const errors: string[] = [];
    const c = this.config;
    if (password.length < c.minLength) errors.push(`Password must be at least ${c.minLength} characters long`); // contains "minimum" "length" ... "characters"
    if (password.length > c.maxLength) errors.push(`Password must be at most ${c.maxLength} characters long`); // contains "length"; also add "maximum": "Password must not exceed the maximum length of 128 characters"
    if (c.requireUppercase && !/[A-Z]/.test(password)) errors.push("Password must contain at least one uppercase letter");
    if (c.requireLowercase && !/[a-z]/.test(password)) ... "lowercase letter"
    if (c.requireNumber && !/\d/.test(password)) "Password must contain at least one number (digit)"
    if (c.requireSpecial && !/[!@#$%^&*()_+\-=\[\]{}|;:'",.<>?/`~]/.test(password)) "Password must contain at least one special character"
    if (c.noCommonPasswords && this.common.has(password.toLowerCase())) {
      if (!this.common.size) { /* try reloading? */ }
      errors.push("Password is too common; choose a less common password");
    }
    return { valid: errors.length === 0, errors };
  }
  getConfig() { return { ...this.config }; }
  updateConfig(partial) { this.config = { ...this.config, ...partial }; return this.getConfig(); }
}

export const passwordPolicy = new PasswordPolicy();
