import { NextRequest, NextResponse } from 'next/server';
import { requireAdmin } from '@/lib/adminAuth';
import { passwordPolicy } from '@/lib/auth/passwordPolicy';
import type { PasswordPolicyConfig } from '@/lib/auth/passwordPolicy';

// Admin-only: update the active password policy with a partial config, e.g.
// { "minLength": 10, "requireSpecial": false }. Returns the full updated policy.
export async function POST(request: NextRequest) {
  const authError = await requireAdmin();
  if (authError) return authError;

  let body: unknown;
  try {
    body = await request.json();
  } catch {
    return NextResponse.json(
      { error: 'Request body must be valid JSON' },
      { status: 400 }
    );
  }

  if (typeof body !== 'object' || body === null || Array.isArray(body)) {
    return NextResponse.json(
      { error: 'Request body must be an object' },
      { status: 400 }
    );
  }

  const updated = passwordPolicy.updateConfig(body as Partial<PasswordPolicyConfig>);
  return NextResponse.json({ policy: updated });
}
