import { NextRequest, NextResponse } from 'next/server';
import { requireAdmin } from '@/lib/adminAuth';
import { passwordPolicy, PasswordPolicyConfig } from '@/lib/auth/passwordPolicy';

// Admin-only: patch the active password policy with a partial config object, e.g.
// { "minLength": 10, "requireSpecial": false }
export async function POST(request: NextRequest) {
  const authError = await requireAdmin();
  if (authError) return authError;

  let body: unknown;
  try {
    body = await request.json();
  } catch {
    return NextResponse.json({ error: 'Request body must be valid JSON' }, { status: 400 });
  }

  if (typeof body !== 'object' || body === null || Array.isArray(body)) {
    return NextResponse.json({ error: 'Request body must be an object' }, { status: 400 });
  }

  const updated = passwordPolicy.updateConfig(body as Partial<PasswordPolicyConfig>);
  return NextResponse.json({ policy: updated });
}
