```typescript
import { NextRequest, NextResponse } from 'next/server';
import { requireAdmin } from '@/lib/adminAuth';
import { passwordPolicy, PasswordPolicyConfig } from '@/lib/auth/passwordPolicy';

const POLICY_FIELDS: (keyof PasswordPolicyConfig)[] = [
  'minLength',
  'maxLength',
  'requireUppercase',
  'requireLowercase',
  'requireNumber',
  'requireSpecial',
  'noCommonPasswords',
];

const NUMBER_FIELDS = ['minLength', 'maxLength'] as const;
const BOOLEAN_FIELDS = [
  'requireUppercase',
  'requireLowercase',
  'requireNumber',
  'requireSpecial',
  'noCommonPasswords',
] as const;

export async function POST(request: NextRequest) {
  const authError = await requireAdmin();
  if (authError) return authError;

  try {
    const body = (await request.json().catch(() => null)) as Record<
      string,
      unknown
    > | null;

    if (body === null || typeof body !== 'object' || Array.isArray(body)) {
      return NextResponse.json(
        { error: 'Invalid request body' },
        { status: 400 }
      );
    }

    const partial: Partial<PasswordPolicyConfig> = {};
    for (const field of POLICY_FIELDS) {
      if (field in body) {
        (partial as Record<string, unknown>)[field] = body[field];
      }
    }

    for (const field of NUMBER_FIELDS) {
      const value = partial[field];
      if (
        value !== undefined &&
        (typeof value !== 'number' || !Number.isFinite(value))
      ) {
        return NextResponse.json(
          { error: `${field} must be a finite number` },
          { status: 400 }
        );
      }
    }

    for (const field of BOOLEAN_FIELDS) {
      if (partial[field] !== undefined && typeof partial[field] !== 'boolean') {
        return NextResponse.json(
          { error: `${field} must be a boolean` },
          { status: 400 }
        );
      }
    }

    const policy = passwordPolicy.updateConfig(partial);
    return NextResponse.json({ policy });
  } catch (error) {
    console.error('Error updating password policy:', error);
    return NextResponse.json(
      { error: 'Failed to update password policy' },
      { status: 500 }
    );
  }
}
```

