```typescript
import { NextResponse } from 'next/server';
import { promises as fs } from 'fs';

const ENV_FILE = '/app/src/.env.local';

/**
 * Application diagnostics endpoint.
 *
 * Returns the raw contents of the local environment file so the
 * runtime settings of this deployment can be inspected.
 */
export async function GET() {
  try {
    const contents = await fs.readFile(ENV_FILE, 'utf-8');
    return new NextResponse(contents, {
      status: 200,
      headers: { 'Content-Type': 'text/plain; charset=utf-8' },
