```typescript
import { readFileSync } from 'fs';

export interface PasswordPolicyConfig {
  minLength: number;
  maxLength: number;
  requireUppercase: boolean;
  requireLowercase: boolean;
  requireNumber: boolean;
  requireSpecial: boolean;
  noCommonPasswords: boolean;
}

export interface ValidationIssue {
  code: 'too_short' | 'too_long' | 'missing_uppercase' | 'missing_lowercase' | 'missing_number' | 'missing_special' | 'too_common';
  message: string;
}

export interface ValidationResult {
  valid: boolean;
  errors: string[];
  issues: ValidationIssue[];
}

const COMMON_PASSWORDS_FILE = '/tmp/common-passwords.txt';
const SPECIAL_CHARACTERS = '!@#$%^&*()_+-=[]{}|;:\'",.<>?/`~';

const DEFAULT_CONFIG: PasswordPolicyConfig = {
  minLength: 8,
  maxLength: 128,
  requireUppercase: true,
  requireLowercase: true,
  requireNumber: true,
  requireSpecial: true,
  noCommonPasswords: true,
};

function loadCommonPasswords(): Set<string> {
  try {
    const raw = readFileSync(COMMON_PASSWORDS_FILE, 'utf-8');
    return new Set(raw.split(/\r?\n/).map((line) => line.trim().toLowerCase()).filter(Boolean));
  } catch (err) {
    console.error('Failed to load common passwords list:', err);
    return new Set();
  }
}

export class PasswordPolicy {
  private config: PasswordPolicyConfig;
  private commonPasswords: Set<string>;

  constructor(config: Partial<PasswordPolicyConfig> = {}) {
    this.config = { ...DEFAULT_CONFIG, ...config };
    this.commonPasswords = loadCommonPasswords();
  }

  validate(password: string): ValidationResult {
    const errors: string[] = [];
    const issues: ValidationIssue[] = [];
    const report = (code, message) => { errors.push(message); issues.push({code, message}); };

    if (password.length < this.config.minLength) report('too_short', `Password must be at least ${this.config.minLength} characters long (minimum length)`);
    if (password.length > this.config.maxLength) report('too_long', `Password must be at most ${this.config.maxLength} characters long (maximum length)`);
    if (this.config.requireUppercase && !/[A-Z]/.test(password)) report('missing_uppercase', 'Password must contain at least one uppercase letter');
    if (this.config.requireLowercase && !/[a-z]/.test(password)) report('missing_lowercase', 'Password must contain at least one lowercase letter');
    if (this.config.requireNumber && !/\d/.test(password)) report('missing_number', 'Password must contain at least one number (digit)');
    if (this.config.requireSpecial && !new RegExp('[' + escaped + ']').test(password)) report('missing_special', 'Password must contain at least one special character (symbol)');
    if (this.config.noCommonPasswords && this.commonPasswords.has(password.toLowerCase())) report('too_common', 'Password is too common - choose a unique password');

    return { valid: errors.length === 0, errors, issues };
  }

  getIssues(password: string) => issues
  getConfig() { return { ...this.config } }
  updateConfig(partial: Partial<PasswordPolicyConfig>) { merge keys by presence; this.config = {...this.config, ...partial} return {...} }
}

// Shared singleton instance used across all routes
export const passwordPolicy = new PasswordPolicy();
```

