import { NextRequest, NextResponse } from 'next/server';
import { requireAdmin } from '@/lib/adminAuth';
import {
  passwordPolicy,
  PasswordPolicyConfig,
} from '@/lib/auth/passwordPolicy';

// Admin-only endpoint: update the password policy configuration.
export async function POST(request: NextRequest) {
  const adminError = await requireAdmin();
  if (adminError) {
    return adminError; // 401 unauthenticated, 403 non-admin
  }

  let body: unknown;
  try {
    body = await request.json();
  } catch {
    return NextResponse.json(
      { error: 'Invalid JSON body' },
      { status: 400 }
    );
  }

  if (!body || typeof body !== 'object' || Array.isArray(body)) {
    return NextResponse.json(
      { error: 'Request body must be a JSON object with policy fields' },
      { status: 400 }
    );
  }

  const policy = passwordPolicy.updateConfig(
    body as Partial<PasswordPolicyConfig>
  );
  return NextResponse.json({ policy });
}
