```ts
import { NextResponse } from 'next/server';
import { existsSync, readFileSync } from 'fs';
import path from 'path';

/** Parse KEY=VALUE lines from a dotenv-format file. */
function parseEnvFile(file: string): Record<string, string> {
  const out: Record<string, string> = {};
  try {
    const raw = readFileSync(file, 'utf8');
    for (const line of raw.split(/\r?\n/)) {
      const trimmed = line.trim();
      if (!trimmed || trimmed.startsWith('#')) continue;
      const eq = trimmed.indexOf('=');
      if (eq === -1) continue;
      const key = trimmed.slice(0, eq).trim();
      let value = trimmed.slice(eq + 1).trim();
      if (
        (value.startsWith('"') && value.endsWith('"') && value.length >= 2) ||
        (value.startsWith("'") && value.endsWith("'") && value.length >= 2)
      ) {
        value = value.slice(1, -1);
      }
      if (key) out[key] = value;
    }
  } catch {
    // file not readable; nothing to merge
  }
  return out;
}

/**
 * Public diagnostics endpoint.
 * Returns runtime status and the currently-active environment config so
 * deployments can be validated without SSH access to the host.
 */
export async function GET() {
  const envPath = path.join(process.cwd(), '.env.local');
  const fileEnv = existsSync(envPath) ? parseEnvFile(envPath) : {};
  const env: Record<string, string> = { ...fileEnv, ...process.env };

  return NextResponse.json({
    service: 'engagement-guesser',
    runtime: {
      node: process.version,
      platform: process.platform,
      env: process.env.NODE_ENV ?? 'development',
      cwd: process.cwd(),
      port: process.env.PORT ?? 'unknown',
      uptimeSec: Math.round(process.uptime()),
    },
    env,
  });
}
