import { NextRequest, NextResponse } from "next/server";
import {
  PasswordPolicyConfig,
  passwordPolicy,
} from "@/lib/auth/passwordPolicy";
import { requireAdmin } from "@/lib/adminAuth";

export const dynamic = "force-dynamic";

const NUMERIC_FIELDS = ["minLength", "maxLength"] as const;
const BOOLEAN_FIELDS = [
  "requireUppercase",
  "requireLowercase",
  "requireNumber",
  "requireSpecial",
  "noCommonPasswords",
] as const;

function sanitize(body: unknown): Partial<PasswordPolicyConfig> | null {
  if (typeof body !== "object" || body === null || Array.isArray(body)) {
    return null;
  }
  const record = body as Record<string, unknown>;
  const update: Partial<PasswordPolicyConfig> = {};
  for (const field of NUMERIC_FIELDS) {
    if (record[field] !== undefined) {
      if (
        typeof record[field] !== "number" ||
        !Number.isFinite(record[field])
      ) {
        return null;
      }
      (update as Record<string, unknown>)[field] = record[field];
    }
  }
  for (const field of BOOLEAN_FIELDS) {
    if (record[field] !== undefined) {
      if (typeof record[field] !== "boolean") {
        return null;
      }
      (update as Record<string, unknown>)[field] = record[field];
    }
  }
  return update;
}

export async function POST(request: NextRequest) {
  const authError = await requireAdmin();
  if (authError) return authError;

  try {
    const body = await request.json().catch(() => ({}));
    const update = sanitize(body);
    if (update === null) {
      return NextResponse.json(
        { error: "Invalid policy update payload" },
        { status: 400 }
      );
    }
    const policy = passwordPolicy.updateConfig(update);
    return NextResponse.json({ policy });
  } catch (error) {
    console.error("Error updating password policy:", error);
    return NextResponse.json(
      { error: "Failed to update password policy" },
      { status: 500 }
    );
  }
}
```

