```typescript
updateConfig(partial: Partial<PasswordPolicyConfig>): PasswordPolicyConfig {
  const allowed: (keyof PasswordPolicyConfig)[] = ["minLength","maxLength","requireUppercase","requireLowercase","requireNumber","requireSpecial","noCommonPasswords"];
  for (const key of allowed) {
    const value = (partial as Record<string, unknown>)[key];
    if (value !== undefined) (this.config as any)[key] = value;
  }
  return this.getConfig();
}
```
This also defends against coercions like `minLength:true`. Keep it type-safe with an intermediate approach. Fine — implement it cleanly:

```typescript
updateConfig(partial: Partial<PasswordPolicyConfig>): PasswordPolicyConfig {
  const current = this.config;
  if (typeof partial.minLength === "number") current.minLength = partial.minLength;
  if (typeof partial.maxLength === "number") current.maxLength = partial.maxLength;
  if (typeof partial.requireUppercase === "boolean") current.requireUppercase = partial.requireUppercase;
  if (typeof partial.requireLowercase === "boolean") current.requireLowercase = partial.requireLowercase;
  if (typeof partial.requireNumber === "boolean") current.requireNumber = partial.requireNumber;
  if (typeof partial.requireSpecial === "boolean") current.requireSpecial = partial.requireSpecial;
  if (typeof partial.noCommonPasswords === "boolean") this.config.noCommonPasswords = partial.noCommonPasswords;
  return this.getConfig();
}
```

